            spec_str = 'T' if spec is T else ('S' if spec is S else ('A' if spec is A else str(spec)))
        elif isinstance(spec, list):
            spec_str = 'list'
        elif isinstance(spec, dict):
            spec_str = 'dict'
        elif isinstance(spec, tuple):
            spec_str = 'tuple'
