            target_str = type(target).__name__

        # Combine spec and target
        if spec_str and target_str:
            parts.append(f'{spec_str}!{target_str}')
        else:
            parts.append(spec_str or target_str)

        # Move to parent scope
        current_scope = scope_dict.get(UP)

    return '/' + '/'.join(reversed(parts))
